import json
import subprocess
import threading
import queue
import sys

def run_task(task_id, command, result_queue):
    try:
        result = subprocess.run(command, shell=True, check=True, text=True, capture_output=True)
        result_queue.put((task_id, "ok"))
    except subprocess.CalledProcessError as e:
        result_queue.put((task_id, "error"))

def main():
    config = json.load(sys.stdin)
    max_parallel = config["max_parallel"]
    tasks = config["tasks"]

    task_queue = queue.Queue()
    for task in tasks:
        task_queue.put(task)

    active_threads = []
    result_queue = queue.Queue()

    for _ in range(max_parallel):
        thread = threading.Thread(target=lambda: run_task(task_queue.get().get("id"), task_queue.get().get("command"), result_queue))
        active_threads.append(thread)
        thread.start()

    for thread in active_threads:
        thread.join()

    while not task_queue.empty():
        task = task_queue.get()
        run_task(task["id"], task["command"], result_queue)

    for _ in range(max_parallel):
        while not result_queue.empty():
            task_id, status = result_queue.get()
            print(f'"{task_id}":"{status}",', end='')

    print('')

if __name__ == "__main__":
    main()
